INSERT INTO player_test_cases (module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('Payments history', 'PAY-003', 'Neuspješni depoziti karticom i EPS-om', 'Negativni', 'High', 'Igrač je prijavljen na staging-2.
